// 선물 찾을 말 목록(쿠팡 파트너스 링크, 2026-11-16 만듦). API 키가 없을 때 선물 추천은 이 안에서만 고른다.
// 칸마다 상품 하나: 링크는 그 상품 하나의 상세 페이지(파트너스 > 상품 링크로 만든 단축 URL), 사진·상품명·값(price)도 그 상품.
// 그 상품 값이 칸의 가격대(BAND_RANGE)에 들어야 한다(테스트가 지킨다). 2026-11-21 전에는 가격을 저장하지 않아 가격대가 어긋난 칸이 많았다(1만원대에 2만원대, 10만원 이상에 2만원대 등)
// → 가격을 읽어 어긋난 칸과 못 읽은 칸을 파트너스 검색(쿠팡 랭킹순)에서 그 가격대에 드는 첫 상품으로 바꿨다. 검색에 그 가격대 상품이 없는 칸은 인기 상품 값에 맞춰 가격대를 옮겼다.
// 쿠팡 검색 화면 링크는 휴대폰 브라우저(Brave 등)에서 '사용권한이 없습니다'로 막혀서 늘 상품 페이지 링크로 둔다(검색 링크는 쓰지 않는다).
// 부모님·어르신 쪽(용돈 박스·건강식품·효도·파크골프·등산·여행)은 2026 어버이날 조사(용돈·의류·여행·건강식품 순)를 보고 더했다.
// 고치려면: 파트너스 > 링크 생성 > 상품 링크에서 칸의 가격대에 드는 상품을 골라 '링크 생성'으로 만든 단축 URL·사진·상품명·값으로 바꾼다(품절되거나 값이 올라 가격대를 벗어나면 바꾼다).
// 쿠팡 상품 페이지는 자동 접속을 막아(403) 값은 파트너스 화면의 상품 카드(.sale-price)에서 읽는다.
//
// 제철 선물(seasons): 크리스마스·연말(11~12월)에 챙기는 선물은 생일·기념일이 가깝지 않을 때 이 철의 것을 먼저 고른다.
//  - 위 목록 중 크리스마스·연말에 어울리는 것은 CHRISTMAS_IDS로 표시한다(파트너스 링크·사진 그대로).
//  - 목록에 없던 크리스마스 소품·케이크 같은 것은 SEASONAL에 더했다(seasonOnly: 철이 아닐 때는 안 보인다). 2026-11-21 파트너스 상품 링크로 만든 단축 URL·사진·상품명이고,
//    쿠팡이 와인·술은 안 팔아서 와인은 와인잔·디캔터로 했다. 가격대는 그 상품 값에 맞췄다(철 상품은 가격 폭이 좁아 찾을 말과 달라진 것이 있다). 고치려면 위와 같이 바꾼다.

export const PRICE_BANDS = ["1", "3", "5", "10"] as const;
export type PriceBand = (typeof PRICE_BANDS)[number];

/** 가격대마다 상품 값(원)의 범위(포함). 1만원대 = 1만~1만9천9백, … 10만원 이상 = 10만 이상 */
export const BAND_RANGE: Record<PriceBand, [number, number]> = {
  "1": [10_000, 19_999],
  "3": [30_000, 39_999],
  "5": [50_000, 59_999],
  "10": [100_000, Number.POSITIVE_INFINITY],
};

/** 선물을 챙기는 철: christmas = 크리스마스·연말(11~12월) */
export type SeasonId = "christmas";

export interface CatalogGift {
  id: string;
  /** 쿠팡 찾을 말 = 화면에 보이는 이름 */
  q: string;
  band: PriceBand;
  /** 어울리는 나이(포함) */
  ages: [number, number];
  /** 기록에 이 말이 있으면 어울린다(취미·취향) */
  tags: string[];
  /** 파트너스 링크(그 상품 하나의 상세 페이지) */
  url: string;
  /** 그 상품 사진(coupangcdn) */
  image: string;
  /** 그 상품 이름(쿠팡 상품명) */
  name: string;
  /** 그 상품 값(원). 파트너스 상품 카드에서 읽은 값이고, band의 BAND_RANGE 안에 든다 */
  price: number;
  /** 든 알레르기(ALLERGENS 코드). 이 알레르기가 있는 사람에게는 고르지 않는다 */
  allergens: string[];
  /** 어울리는 철(크리스마스·연말). 그 철에 생일·기념일이 가깝지 않으면 이것을 먼저 고른다 */
  seasons: SeasonId[];
  /** 그 철에만 보이는 것(크리스마스 소품·케이크 등). 철이 아니면 고르지도, 가이드에 싣지도 않는다 */
  seasonOnly?: boolean;
}

function g(id: string, q: string, band: PriceBand, ages: [number, number], tags: string[], url: string, image: string, name: string, price: number, allergens: string[]): CatalogGift {
  return { id, q, band, ages, tags, url, image, name, price, allergens, seasons: [] };
}

/** 제철 전용(seasonOnly): 크리스마스·연말에만 보이는 선물. g()와 같되 철 표시가 붙고 철이 아니면 고르지도, 가이드에 싣지도 않는다 */
function s(id: string, q: string, band: PriceBand, ages: [number, number], tags: string[], url: string, image: string, name: string, price: number, allergens: string[]): CatalogGift {
  return { id, q, band, ages, tags, url, image, name, price, allergens, seasons: ["christmas"], seasonOnly: true };
}

